import test from'node:test';import assert from'node:assert/strict';import{pathToFileURL}from'node:url';import{finalPnoContractArtifact}from'./pno-final-contract-artifact-v3.mjs';import{harness,trip,deferred,flush}from'./pno-final-contract-harness-v3.mjs';
const artifact=finalPnoContractArtifact();const{readSharedPnoPage}=await import(pathToFileURL(artifact.runtime+'/index.js'));
function transport(owner,stats,pending={}){return async(row,type,page)=>readSharedPnoPage(owner,{}, {hub:row.hub,day:row.pnoSourceDay,proofId:row.proofId,lineId:row.pnoLineId,storeId:row.pnoStoreId,nextStoreId:row.pnoNextStoreId,type,page,count:1},{readCredential:async()=>({}),fetchDetailPage:async(_,locator)=>{stats.reads.push(locator.proofId);stats.active++;stats.peak=Math.max(stats.peak,stats.active);try{if(pending[locator.proofId])await pending[locator.proofId].promise;return{items:[{pno:'000SYN-'+locator.proofId,pack_no:'000BAG-'+locator.proofId}],total:1,sourceValid:true};}finally{stats.active--;}}});}
const stats=()=>({reads:[],active:0,peak:0});
test('DEV003 actual UI+sharedWorker: A/B/C explicit opens, peak2, only latest C data/QR, no background acquisitions',async()=>{const s=stats(),pending={A:deferred(),B:deferred(),C:deferred()},h=harness(transport({},s,pending));const a=h.open(trip('A'));await flush();const b=h.open(trip('B'));await flush();assert.deepEqual(s.reads,['A','B']);const c=h.open(trip('C'));await flush();assert.deepEqual(s.reads,['A','B']);pending.B.resolve();await b;await flush();assert.deepEqual(s.reads,['A','B','C']);assert.equal(s.peak,2);pending.C.resolve();await c;await h.prepared();pending.A.resolve();await a;assert.equal(h.data.rows[0].pno,'000SYN-C');assert.equal(h.data.proofId,'C');assert.equal(h.node('truck-head').children[0].children[1].textContent,'C');const n=h.calls.length;await flush();assert.equal(h.calls.length,n);assert.equal(s.reads.length,3);});
test('DEV003 waiting C canceled on close before slot opens: no C read',async()=>{const s=stats(),pending={A:deferred(),B:deferred()},h=harness(transport({},s,pending));const a=h.open(trip('A'));await flush();const b=h.open(trip('B'));await flush();const c=h.open(trip('C'));await flush();await h.close();pending.A.resolve();pending.B.resolve();await Promise.all([a,b,c]);await h.prepared();assert.deepEqual(s.reads,['A','B']);assert.equal(s.peak,2);assert.equal(h.node('truck-head').children[0].hidden,true);});
test('DEV003 same-trip duplicate opens use real shared inflight/cache; ten viewers still one provider boundary read',async()=>{const s=stats(),owner={},pending={SAME:deferred()},provide=transport(owner,s,pending);const clients=Array.from({length:10},()=>harness(provide)),r=trip('SAME');const jobs=clients.map(h=>h.open(r));await flush();assert.deepEqual(s.reads,['SAME']);const reopen=clients[0].open(r);await flush();assert.deepEqual(s.reads,['SAME']);pending.SAME.resolve();await Promise.all([...jobs,reopen]);await Promise.all(clients.map(h=>h.prepared()));const before=s.reads.length;await clients[0].open(r);await clients[0].prepared();assert.equal(s.reads.length,before);assert.equal(s.peak,1);});
test('DEV003 actual Worker envelope passes admission; missing/foreign identity fails closed',async()=>{const s=stats(),r=trip('ADMISSION'),provide=transport({},s);const page=await provide(r,'total',1),h=harness();assert.doesNotThrow(()=>h.ctx.pnoQrValidatePage009(page,r,{hub:r.hub,type:'total',page:1}));for(const key of ['sourceValid','hub','proofId','day','lineId','sourceStoreId','targetStoreId','type','page'])for(const mode of ['missing','foreign']){const bad={...page};if(mode==='missing')delete bad[key];else bad[key]=key==='page'?2:key==='sourceValid'?false:'FOREIGN';assert.throws(()=>h.ctx.pnoQrValidatePage009(bad,r,{hub:r.hub,type:'total',page:1}));}});
test('DEV003 init and provider failure do not add polling/retry; existing error stays local',async()=>{const h=harness(async()=>{const e=Error('SYNTHETIC_PROVIDER_429');e.status=429;throw e;});for(let i=0;i<10;i++)h.ctx.pnoV18EnsureUi();assert.equal(h.calls.length,0);await h.open();await h.prepared();await flush();assert.equal(h.calls.length,1);assert.equal(h.data.busy,false);assert.equal(h.data.filterRows,null);});
